// ---------------------------------------------------------------------------
// tb_wrom0_wave -- WAVEFORM testbench for wrom0, generated by gen_wave_tb.py
//
// Regenerate:  python3 scripts/rom_char/gen_wave_tb.py wrom0
//
// This TB drives ONLY LEGAL cycles. Every constraint the model checks is
// respected with margin, so a clean run prints nothing and `mismatch` stays
// low for the whole simulation -- what you are meant to be looking at is the
// DATA, not a failure.
//
// Timing below is MEASURED (SS_1p6V_100C corner, via wrom0.sv):
//     access 41.0592 ns / precharge 14.8779 ns / setup 0.0480 ns
// The cycle built from it:
//     low phase  = 14.8779 * PRE_MARGIN
//     high phase = 41.0592 * EVAL_MARGIN
//     addr0 lands = 0.0480 * SETUP_MARGIN before the rising edge
// so the period is roughly 75.7 ns -- this macro is SLOW, do not expect
// the waves to look like a synchronous SRAM.
//
// WHAT TO PUT IN THE WAVE WINDOW (top to bottom)
//     clk0, cs0        the drive
//     phase            PRECHARGE / EVALUATE / VALID, as ASCII
//     addr0            the address being read (radix: unsigned)
//     dout0            the raw output -- all ones for half of every cycle
//     dout_cap         the value captured at the falling edge  <-- THE DATA
//     expected         the .bin content at addr0
//     mismatch         must stay 0
//
// VIVADO, batch from the repository root -- this is the one that ends with a
// wave database you can open:
//     xvlog -sv output/verilog/wrom0.sv tests/wave/tb_wrom0_wave.v
//     xelab -debug typical tb_wrom0_wave -s tb_wrom0_wave_sim
//     xsim tb_wrom0_wave_sim -tclbatch tests/wave/tb_wrom0_wave.tcl
//     xsim --gui tb_wrom0_wave_sim.wdb
// -debug typical is not optional: without it nothing is logged and the wave
// window is empty.
//
// VIVADO GUI: add wrom0.sv and this file to a simulation fileset, set
// tb_wrom0_wave as the simulation top, Run Behavioral Simulation. Set
// `phase` to ASCII radix and addr0 to unsigned once the window is up.
//
// iverilog, for the same waves without Vivado:
//     iverilog -g2012 -o /tmp/wrom0_wave.vvp \
//              output/verilog/wrom0.sv tests/wave/tb_wrom0_wave.v
//     vvp /tmp/wrom0_wave.vvp && gtkwave tb_wrom0_wave.vcd
// ---------------------------------------------------------------------------
`timescale 1ns / 1ps

module tb_wrom0_wave;

  // ---- what the run covers ------------------------------------------------
  parameter integer START_ADDR = 100;
  parameter integer N_READS    = 64;

  // Margins on the MEASURED minimums. 1.0 would sit exactly on the constraint
  // and a wave viewer cannot show you whether you are on the right side of an
  // equality, so they are deliberately above it.
  parameter real PRE_MARGIN   = 1.50;   // low  phase  = T_PRE_NS * this
  parameter real EVAL_MARGIN  = 1.30;   // high phase  = ACCESS_NS * this
  // The address is placed SETUP_NS * this before the rising edge, and NOT a
  // whole low phase before it. Those are very different pictures: a whole low
  // phase is 465x the constraint and shows the reader nothing except
  // that the testbench was generous. At this margin the gap in the wave IS
  // the .lib's setup_rising, which is the point of looking at it.
  //
  // BELOW 1.0 IT IS A VIOLATION, deliberately: regenerate with
  // --setup-margin 0.6 and the model reports the setup violation on every
  // cycle. That is the other picture worth taking.
  parameter real SETUP_MARGIN = 2.00;   // addr0 -> clk0 rise = SETUP_NS * this

  // The data the model loads. NOT rom_configs/wrom0.bin: that file is raw
  // binary and $readmemb cannot read it (it aborts on the first byte and the
  // array stays X). wrom0_rom.mem is the same contents as $readmemb text,
  // written by gen_wave_tb.py at the same time as this file.
  //
  // The path is absolute because a simulator's working directory is its own
  // business -- Vivado runs from <project>.sim/sim_1/behav/xsim, where a
  // relative path does not resolve. Override it if the tree moves:
  //     xelab -generic_top "INIT_FILE=/other/path/wrom0_rom.mem" ...
  parameter INIT_FILE = "/home/hpw/openram-rom-libgen/tests/wave/wrom0_rom.mem";

  localparam real T_PRE  = 14.8779;
  localparam real ACCESS = 41.0592;
  localparam real SETUP  = 0.0480;
  localparam real T_LOW  = T_PRE  * PRE_MARGIN;
  localparam real T_HIGH = ACCESS * EVAL_MARGIN;
  // The address sits here, inside the low phase -- the bitlines are held at
  // VDD throughout, so moving the address costs nothing until the edge.
  localparam real T_SETUP = SETUP * SETUP_MARGIN;

  localparam integer WIDTH     = 32;
  localparam integer ADDR_BITS = 11;
  localparam integer DEPTH     = 1064;

  reg                  clk0  = 1'b0;
  reg                  cs0   = 1'b0;
  reg  [10:0]  addr0 = {ADDR_BITS{1'b0}};
  wire [31:0] dout0;

  wrom0 #(.INIT_FILE(INIT_FILE)) dut (
    .clk0 (clk0),
    .cs0  (cs0),
    .addr0(addr0),
    .dout0(dout0)
  );

  // ---- observation only; none of this exists in the macro -----------------
  reg  [31:0] dout_cap = {WIDTH{1'b1}};  // value at the capture point
  reg  [31:0] expected = {WIDTH{1'b0}};  // .bin content at addr0
  reg                  mismatch = 1'b0;
  reg  [8*9:1]         phase    = "IDLE";
  integer              read_idx = 0;
  integer              errors   = 0;

  always @(*) expected = dut.mem[addr0];

  // ---- the run ------------------------------------------------------------
  integer i;
  initial begin
    $dumpfile("tb_wrom0_wave.vcd");
    $dumpvars(0, tb_wrom0_wave);

    $display("=== wrom0 waveform run: %0d reads from address %0d ===",
             N_READS, START_ADDR);
    $display("    cycle = %.3f ns low + %.3f ns high (measured SS_1p6V_100C)",
             T_LOW, T_HIGH);

    // The FIRST precharge is not optional. Power-up leaves the bitlines
    // undefined and the model only puts them at VDD on a clk0 fall, so the
    // run opens with cs0 low and a full low phase before anything is read.
    clk0  = 1'b0;
    cs0   = 1'b0;
    phase = "PRECHARGE";
    #(T_LOW);
    cs0 = 1'b1;

    for (i = 0; i < N_READS; i = i + 1) begin
      read_idx = i;

      // The low phase runs with the PREVIOUS address still on the pins; the
      // new one goes on T_SETUP before the edge, so the gap you measure in
      // the wave window is the .lib's setup_rising and nothing else.
      //
      // T_SETUP is tens of picoseconds and the cycle is tens of nanoseconds,
      // so at full-cycle zoom the address and the clock edge look
      // simultaneous. THAT IS THE MEASUREMENT: zoom to the edge to see it.
      phase = "PRECHARGE";
      #(T_LOW - T_SETUP);
      addr0 = (START_ADDR + i) % DEPTH;
      #(T_SETUP);

      clk0  = 1'b1;
      phase = "EVALUATE";
      // dout0 is NOT the data yet; the bitlines are still discharging.
      #(ACCESS);
      phase = "VALID";
      #(T_HIGH - ACCESS);

      // CAPTURE, at the point a real consumer would: just before the fall,
      // with the address and cs0 still held. The macro does give a little
      // slack past the edge -- T_FALL_NS, the .lib's falling_edge arc on
      // dout0, is how long the precharge PMOS takes to pull the bitlines
      // back up -- but that window is a few nanoseconds and it is not what
      // a testbench should be spending. Capture before the edge.
      dout_cap = dout0;
      mismatch = (dout0 !== expected);
      if (mismatch) begin
        errors = errors + 1;
        $display("MISMATCH %0t: addr %0d -> dout0 %h, .bin says %h",
                 $time, addr0, dout0, expected);
      end
      $display("%8t  addr %4d  dout %h", $time, addr0, dout0);

      clk0  = 1'b0;
      phase = "PRECHARGE";
      #(1.0);
      mismatch = 1'b0;
      #(T_LOW - 1.0);
    end

    // Tail: one deselected cycle. cs0 low keeps the precharge on through the
    // whole high phase, so dout0 stays at all ones with clk0 toggling -- the
    // shape to recognise when a read "returns 0xFF...F for no reason".
    phase = "IDLE";
    cs0   = 1'b0;
    clk0  = 1'b1;
    #(T_HIGH);
    clk0  = 1'b0;
    #(T_LOW);

    if (errors == 0)
      $display("=== done: %0d reads, every one matched wrom0.bin ===", N_READS);
    else
      $display("=== done: %0d MISMATCHES in %0d reads ===", errors, N_READS);
    $finish;
  end

endmodule
